namespace Linx.Internet.Application.Framework.Web
{
    using System;
    using System.Collections.Generic;
    using System.Diagnostics;
    using System.Linq;
    using System.Reflection;
    using System.Text;
    using Linx.Internet.Application.Framework.Classes;

    /// <summary>
    /// Class AssemblyResources
    /// </summary>
    public static class AssemblyResources
    {
        /// <summary>
        /// Metodo LoadEmbeddedResources
        /// </summary>
        /// <param name="t">parametro tipo type</param>
        /// <param name="resourceName">Parametro tipo String</param>
        /// <returns>Retorna um Dicionario contendo string como key e um Array de Byte</returns>
        public static Dictionary<string, EmbeddedFile> LoadEmbeddedResources(Type t, string moduleName = "", string resourceName = "~")
        {
            Assembly executingAssembly = Assembly.GetAssembly(t);

            string assemblyName = executingAssembly.FullName.Split(',')[0];
            string assemblyVersion =  executingAssembly.GetName().Version.ToString().Replace(".", "-");
            string[] arquivos = executingAssembly.GetManifestResourceNames();

            Dictionary<string, EmbeddedFile> conteudoEmbeddedResources = new Dictionary<string, EmbeddedFile>(arquivos.Length);

            for (int i = 0; i < arquivos.Length; i++)
            {
                var nomeArquivo = arquivos[i];

                if (nomeArquivo.IndexOf(".app.", StringComparison.InvariantCultureIgnoreCase) == -1 && nomeArquivo.IndexOf(".applogin.", StringComparison.InvariantCultureIgnoreCase) == -1 && nomeArquivo.IndexOf(".lib.", StringComparison.InvariantCultureIgnoreCase) == -1 && nomeArquivo.IndexOf(".selfhost.", StringComparison.InvariantCultureIgnoreCase) == -1)
                    continue;

                StringBuilder url = new StringBuilder();

                if (moduleName.Length > 0)
                {
                    url.Append(".");
                    url.Append(moduleName);
                    url.Append(".v");
                    url.Append(assemblyVersion.ToLower());
                    url.Append("-" + Common.IsAssemblyDebugBuild(executingAssembly));
                }
                url.Append(nomeArquivo.Replace(assemblyName, string.Empty));

                using (System.IO.Stream s = executingAssembly.GetManifestResourceStream(nomeArquivo))
                {
                    if (s != null)
                    {
                        byte[] block = new byte[s.Length];
                        s.Read(block, 0, block.Length);

                        string[] fileNameArr = url.ToString().Split('.');


                        EmbeddedFile arquivoEmbedado = new EmbeddedFile();
                        arquivoEmbedado.ModuleName = moduleName;
                        arquivoEmbedado.FullPath = url.ToString();
                        arquivoEmbedado.FileName = string.Concat(fileNameArr[fileNameArr.Length - 2], ".", fileNameArr[fileNameArr.Length - 1]);
                        arquivoEmbedado.FileNameFlat = fileNameArr[fileNameArr.Length - 2];
                        arquivoEmbedado.Extension = System.IO.Path.GetExtension(arquivoEmbedado.FileName);
                        arquivoEmbedado.Url = string.Concat(string.Join("/", fileNameArr, 0, fileNameArr.Count() - 1), arquivoEmbedado.Extension);
                        arquivoEmbedado.FullPathIO = arquivoEmbedado.Url.Replace("/", @"\");
                        arquivoEmbedado.FullPathZip = arquivoEmbedado.Url.Substring(1).Replace("/", @"\");

                        var requireId = string.Concat(string.Join("/", fileNameArr, 4, fileNameArr.Count() - 5), arquivoEmbedado.Extension); 
                        arquivoEmbedado.RequireId = (arquivoEmbedado.Extension == ".js" ? string.Concat("pkg_", moduleName, "/", requireId.Replace(".js", string.Empty)) : string.Concat("text!pkg_", moduleName, "/", requireId));
                        arquivoEmbedado.Bytes = block;
                        arquivoEmbedado.CRC32 = Linx.Internet.Application.Common.ParallelCRC.ComputeX2(block);
                        arquivoEmbedado.LastModified = DateTime.Now;

                        conteudoEmbeddedResources.Add(string.Concat(resourceName, url), arquivoEmbedado);
                    }
                }
            }

            return conteudoEmbeddedResources;
        }
    }
}
